"""Build the assignment PDF from measured results, with personal fields blank."""
import argparse
import json
from pathlib import Path
from xml.sax.saxutils import escape
from reportlab.lib import colors
from reportlab.lib.pagesizes import A4
from reportlab.lib.styles import getSampleStyleSheet, ParagraphStyle
from reportlab.lib.units import mm
from reportlab.platypus import SimpleDocTemplate, Paragraph, Spacer, Table, TableStyle, Image, PageBreak

ROOT=Path(__file__).resolve().parents[1]
INK=colors.HexColor('#173447')
TEAL=colors.HexColor('#167d9a')
PALE=colors.HexColor('#edf5f7')


def build(results=ROOT/'results',output=ROOT/'output/pdf/assignment_report.pdf'):
    results,output=Path(results),Path(output)
    metrics=json.loads((results/'metrics.json').read_text())
    config=metrics['config']
    styles=getSampleStyleSheet()
    styles.add(ParagraphStyle(name='TitleCustom',fontName='Helvetica-Bold',fontSize=25,leading=30,textColor=INK,spaceAfter=17))
    styles.add(ParagraphStyle(name='SectionCustom',fontName='Helvetica-Bold',fontSize=17,leading=22,textColor=INK,spaceAfter=13))
    styles.add(ParagraphStyle(name='BodyCustom',fontName='Helvetica',fontSize=10,leading=14,spaceAfter=9,textColor=INK))
    styles.add(ParagraphStyle(name='SmallCustom',fontName='Helvetica',fontSize=8.3,leading=11,spaceAfter=7,textColor=INK))
    styles.add(ParagraphStyle(name='FormulaCustom',fontName='Courier',fontSize=9,leading=13,spaceAfter=8,textColor=INK))
    styles.add(ParagraphStyle(name='CaptionCustom',fontName='Helvetica-Oblique',fontSize=8.3,leading=11,spaceAfter=10,textColor=INK))
    story=[]
    def p(text,style='BodyCustom'):story.append(Paragraph(text,styles[style]))
    def h(text):p(text,'SectionCustom')
    def page():story.append(PageBreak())
    def table(rows,widths,font=8.3):
        converted=[[Paragraph(escape(str(v)),styles['SmallCustom']) for v in row] for row in rows]
        t=Table(converted,colWidths=widths,repeatRows=1,hAlign='LEFT')
        t.setStyle(TableStyle([('BACKGROUND',(0,0),(-1,0),PALE),('LINEBELOW',(0,0),(-1,0),.8,TEAL),
            ('VALIGN',(0,0),(-1,-1),'TOP'),('LEFTPADDING',(0,0),(-1,-1),7),('RIGHTPADDING',(0,0),(-1,-1),7),
            ('TOPPADDING',(0,0),(-1,-1),5),('BOTTOMPADDING',(0,0),(-1,-1),4),
            ('ROWBACKGROUNDS',(0,1),(-1,-1),[colors.white,colors.HexColor('#f7f9fa')])]))
        story.extend([t,Spacer(1,10)])
    def image(name,width=170*mm):
        im=Image(str(results/name))
        im.drawHeight=im.imageHeight/im.imageWidth*width;im.drawWidth=width
        story.append(im)
    def stat(group,key,percent=False):
        v=group[key];factor=100 if percent else 1
        return f'{v["mean"]*factor:.2f} +/- {v["std"]*factor:.2f}' if percent else f'{v["mean"]:.3f} +/- {v["std"]:.3f}'
    lookup={(g['method'],g['condition']):g for g in metrics['aggregate']}
    modes=('softmax','evidential');conditions=('clean','noise_0.3','noise_0.6')
    cnames={'clean':'Clean','noise_0.3':'Noise 0.3','noise_0.6':'Noise 0.6'}
    ec=lookup['evidential','clean'];sc=lookup['softmax','clean']
    en=lookup['evidential','noise_0.6'];sn=lookup['softmax','noise_0.6']

    p('CISC3024 / AI Assignment #2','SmallCustom')
    p('Probabilistic digit recognition<br/>with evidential uncertainty','TitleCustom')
    p('A local adaptation of a WACV 2024 computer vision method','SectionCustom')
    p('Report prepared: 6 October 2026. All code, experiments, figures, and report text were generated by the AI agent. Personal fields are intentionally blank at the student\'s request.','SmallCustom')
    p('Student name: ____________________________________________<br/>Student ID: ______________________________________________')
    h('1. How AI found the algorithm')
    p('The agent first extracted and visually inspected AIassign2.pdf, then recorded its six report requirements and instruction that the student must not write code. The workspace contained the assignment but no implementation or configured Git remote.')
    p('The search focused on recent probabilistic image classification methods and primary research sources. Queries included "2024 2025 evidential deep learning image classification Dirichlet paper official" and "Fisher Information-based Evidential Deep Learning ICML 2023 paper". The agent considered I-EDL [4], HENN [5], and the variance-based evidential method [1].')
    p('The selected paper is <b>Evidential Uncertainty Quantification: A Variance-Based Perspective</b>, by Ruxiao Duan, Brian Caffo, Harrison X. Bai, Haris I. Sair, and Craig Jones, WACV 2024, pp. 2132-2141 [1]. Its preprint appeared in November 2023. The choice offers an explicit probability derivation, class-level outputs, and manageable local computation; it is not a claim that this is the newest method available in 2026.')
    p('The agent verified the conference metadata, read the primary paper through arXiv, and checked formulas against the authors\' reference implementation [2]. The research trail and the exact implementation scope are recorded in docs/research_log.md.')
    p(f'<b>Measured outcome.</b> Over {len(config["seeds"])} seeds, the evidential classifier achieved {ec["accuracy"]["mean"]*100:.2f}% clean-test accuracy (softmax: {sc["accuracy"]["mean"]*100:.2f}%). Under severe pixel noise, evidential predictive NLL was {en["nll"]["mean"]:.3f}, compared with {sn["nll"]["mean"]:.3f} for softmax. These are this project\'s results, not reproduced paper benchmark numbers.')

    page();h('2. Algorithm and probability theory')
    p('The model uses a two-level probability model: the one-hot label y is categorical given a class-probability vector p, while p itself follows a Dirichlet distribution. A neural network predicts positive concentration parameters alpha. In this implementation alpha = softplus(logits) + 1, a smooth evidence transformation with a unit uniform prior.')
    p('y | p ~ Categorical(p) ; p | x ~ Dirichlet(alpha(x))<br/>S = sum(alpha) ; m = E[p | x] = alpha / S<br/>prediction = argmax(m)','FormulaCustom')
    p('The distinction matters: two images may have the same predictive mean m but different Dirichlet strength S. The larger strength represents greater concentration of the learned probability distribution. Network weights remain deterministic; this is a probability-based classifier rather than a Bayesian posterior over weights.')
    p('Training follows the paper\'s supervised objective (Eqs. 5-7): predictive negative log likelihood plus a KL penalty against a uniform Dirichlet. The target-class concentration is replaced by 1 only in the penalty, so regularization penalizes unsupported evidence for other classes.')
    p('L = log(S) - log(alpha_true) + lambda * KL<br/>KL = KL(Dirichlet(masked_alpha) || Dirichlet(ones))<br/>masked_alpha = y + (1-y) * alpha','FormulaCustom')
    p('The law of total covariance separates uncertainty under the fitted model [1]. Let C = diag(m) - m m^T. The paper\'s Eqs. 19-27 yield:')
    p('Cov(y | x) = C<br/>Epistemic covariance = C / (S+1)<br/>Aleatoric covariance = S*C / (S+1)','FormulaCustom')
    p('A covariance diagonal gives uncertainty for each class; its trace gives sample uncertainty. Correlation divides each covariance entry by the corresponding standard deviations (Eq. 28). Aleatoric uncertainty describes randomness conditional on the model; epistemic uncertainty describes dispersion of its predicted probability vector. These interpretations depend on the Dirichlet assumptions and training quality.')
    image('class_uncertainty.png')
    p('Figure 1. Seed 42: the clean test image with highest epistemic uncertainty is an 8 predicted as 5. Its broad class uncertainty reflects low evidence. Negative off-diagonal correlation comes from mutually exclusive labels; it is not an empirical confusion rate.','CaptionCustom')

    page();h('3. How AI implemented and verified it')
    p('The agent wrote an independent NumPy MLP with manual backpropagation and Adam. SciPy provides special functions for the KL loss and its analytic gradient. scikit-learn supplies the bundled digit data, stratified splits, and standard metrics; Matplotlib draws the figures. No code was copied from the reference repository.')
    table([['Module','Purpose'],['src/evidential.py','Dirichlet loss, gradients, network, covariance, entropy, checkpoints'],
           ['src/experiment.py','Paired experiments, validation selection, metrics, plots'],
           ['src/predict.py','Prediction on a bundled digit or an 8x8 grayscale image'],
           ['src/report.py','Generate this PDF directly from results/metrics.json']], [53*mm,117*mm])
    p('<b>Scope.</b> Implemented paper Eqs. 5-10 and 19-28. Adapted the backbone to a small MLP and the output to softplus + 1. The full active domain adaptation loop, unsupervised uncertainty guidance, certainty pseudo-labeling, and Office-Home/VisDA experiments were not implemented. The result is a classification/uncertainty adaptation, not a full reproduction.')
    p('<b>Checks performed.</b> Nine pytest cases passed. The analytic loss gradient agreed with central finite differences. Covariance components agreed with 150,000 sampled Dirichlet probability vectors. Other checks covered decomposition, covariance row sums and positive semidefiniteness, evidence scaling, invalid inputs, checkpoint round trips, training loss reduction, and disjoint split indices.')
    h('4. Experiment settings')
    table([['Setting','Value'],['Dataset [3]','1,797 optical digit images; 8x8 pixels; 10 classes (not MNIST)'],
           ['Preprocessing / splits','Pixels divided by 16; 1,077 train / 360 validation / 360 test'],
           ['Backbone / optimizer','64-128-10 ReLU MLP; Adam; learning rate 0.003; batch 64'],
           ['Training / selection',f'{config["epochs"]} epochs; restore minimum clean validation predictive NLL'],
           ['Evidential KL','Linear ramp to 0.01 over the first 10 epochs'],
           ['Repeated runs',', '.join(map(str,config['seeds']))],
           ['Test corruption','Gaussian noise SD 0.3 and 0.6 on normalized pixels; clip to [0,1]']], [53*mm,117*mm])
    p('Both methods use the same initialization, batches, splits, and test noise within a seed. Training uses clean data only; test images never guide checkpoint selection. Seeds vary both the split and training randomness. Mean +/- sample SD summarizes run variability; overlapping random splits do not constitute independent datasets or a significance test. All models, split indices, prediction arrays, and histories are saved.','SmallCustom')

    page();h('4. Experiment results')
    p('Tables report mean +/- sample SD across the three runs. Accuracy and macro F1 are percentages. NLL is predictive negative log likelihood; lower is better. The Brier score sums squared probability errors over all 10 classes. ECE uses 15 equal-width confidence bins; it is a finite-sample calibration estimate.')
    rows=[['Condition / method','Accuracy (%)','Macro F1 (%)','NLL']]
    for condition in conditions:
        for mode in modes:
            g=lookup[mode,condition]
            rows.append([f'{cnames[condition]} / {mode}',stat(g,'accuracy',True),stat(g,'macro_f1',True),stat(g,'nll')])
    table(rows,[48*mm,40*mm,40*mm,42*mm])
    rows=[['Condition / method','Brier score','ECE']]
    for condition in conditions:
        for mode in modes:
            g=lookup[mode,condition];rows.append([f'{cnames[condition]} / {mode}',stat(g,'brier'),stat(g,'ece')])
    table(rows,[70*mm,50*mm,50*mm])
    image('summary.png')
    p('Figure 2. Accuracy declines under corruption for both methods. The right plot shows the first seed\'s validation NLL over training; each method restores its own best epoch.','CaptionCustom')
    p('Softmax performs better on clean NLL, Brier score, and ECE. The evidential model has lower mean noisy NLL and ECE here, but moderate-noise accuracy is slightly lower. The severe-noise accuracy advantage is small compared with run variability. These observations support a limited probabilistic robustness benefit, not universal superiority.','SmallCustom')

    page();h('4. Uncertainty analysis and limitations')
    p('Variance-based and entropy-based uncertainty use the same trained evidential network; changing the uncertainty formula does not change digit predictions. Their error-detection AUROC treats a mistake as the positive class. A larger score should rank incorrect images above correct images; 0.5 represents chance ranking. This is not an out-of-distribution detection experiment.')
    rows=[['Condition','Variance EU AUROC','Entropy EU AUROC','Mean AU / EU']]
    for condition in conditions:
        g=lookup['evidential',condition]
        rows.append([cnames[condition],stat(g,'error_auc_epistemic'),stat(g,'error_auc_entropy_epistemic'),
                     f'{g["mean_aleatoric"]["mean"]:.4f} / {g["mean_epistemic"]["mean"]:.4f}'])
    table(rows,[30*mm,47*mm,47*mm,46*mm])
    image('uncertainty.png')
    p('Figure 3. Seed 42 error-score distributions and clean/severely noisy uncertainty means. Table entries above aggregate all three seeds; the plots use one seed. AU and EU use covariance-trace units.','CaptionCustom')
    image('uncertain_examples.png',width=153*mm)
    p('Figure 4. Seed 42\'s eight most epistemically uncertain clean test images, including correct and incorrect predictions. High uncertainty does not imply that a prediction must be wrong.','CaptionCustom')
    p('Both mean AU and EU increase under corruption, and variance EU ranks errors better than entropy EU in these runs. Severe-noise error ranking remains limited (about 0.67 AUROC), and evidential ECE remains high. The small dataset, fixed hyperparameters, random image splits, and synthetic noise limit generalization. Digit pixels do not approximate the paper\'s large cross-domain image benchmark. No automatic rejection threshold was tuned.','SmallCustom')

    page();h('5. What I learnt from this AI assignment')
    p('Personal learning reflection:')
    for _ in range(6):p('_____________________________________________________________________')
    story.append(Spacer(1,10))
    h('6. Webpage link of my source code')
    p('Source-code webpage: ______________________________________________')
    p('Work remains local at the student\'s request. This field is intentionally blank. A webpage for this project\'s source code is required before submission; the authors\' reference repository does not replace it.','SmallCustom')
    h('References and reproducibility')
    refs=[
      ('[1] Duan, R., Caffo, B., Bai, H. X., Sair, H. I., and Jones, C. (2024). Evidential Uncertainty Quantification: A Variance-Based Perspective. WACV, 2132-2141. Primary paper:', 'https://arxiv.org/abs/2311.11367'),
      ('[2] Duan et al. Authors\' reference implementation:', 'https://github.com/KerryDRX/EvidentialADA'),
      ('[3] scikit-learn. load_digits: bundled optical recognition of handwritten digits:', 'https://scikit-learn.org/stable/modules/generated/sklearn.datasets.load_digits.html'),
      ('[4] Deng et al. (2023). Uncertainty Estimation by Fisher Information-based Evidential Deep Learning. ICML:', 'https://proceedings.mlr.press/v202/deng23b.html'),
      ('[5] Li, C., et al. (2024). Hyper Evidential Deep Learning to Quantify Composite Classification Uncertainty. ICLR 2024. Considered as an alternative during algorithm selection.', None),
    ]
    for text,url in refs:
        p(escape(text)+(f' <link href="{escape(url)}" color="#167d9a">{escape(url)}</link>' if url else ''),'SmallCustom')
    p('Reproduce: .venv/bin/python -m pytest -q ; .venv/bin/python -m src.experiment ; .venv/bin/python -m src.report. Exact dependencies are recorded in requirements-lock.txt. Detailed AI steps and publication URLs are in docs/research_log.md. Raw measurements are in results/metrics.json and results/metrics.csv.','SmallCustom')
    p('Report status: local draft. Student details, personal reflection, and publication link require completion. No public publishing or Moodle submission has been performed.','SmallCustom')

    output.parent.mkdir(parents=True,exist_ok=True)
    def footer(canvas,doc):
        canvas.setStrokeColor(TEAL);canvas.setLineWidth(.7)
        canvas.line(20*mm,17*mm,190*mm,17*mm)
        canvas.setFont('Helvetica',8);canvas.setFillColor(INK)
        canvas.drawString(20*mm,12*mm,'CISC3024 | AI Assignment #2 | 6 October 2026')
        canvas.drawRightString(190*mm,12*mm,f'{doc.page}')
    doc=SimpleDocTemplate(str(output),pagesize=A4,leftMargin=20*mm,rightMargin=20*mm,
                         topMargin=19*mm,bottomMargin=23*mm,
                         title='Probabilistic Digit Recognition with Evidential Uncertainty',author='')
    doc.build(story,onFirstPage=footer,onLaterPages=footer)
    print(output)


if __name__=='__main__':
    parser=argparse.ArgumentParser(description=__doc__)
    parser.add_argument('--results',type=Path,default=ROOT/'results')
    parser.add_argument('--output',type=Path,default=ROOT/'output/pdf/assignment_report.pdf')
    args=parser.parse_args();build(args.results,args.output)
